import{_ as e,o as t,c as o,a0 as i}from"./chunks/framework.DZqO77tS.js";const m=JSON.parse('{"title":"さあ！始めよう！","description":"","frontmatter":{},"headers":[],"relativePath":"docs/hack/getting-started.md","filePath":"docs/hack/getting-started.md"}'),r={name:"docs/hack/getting-started.md"};function c(l,a,n,s,d,h){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="さあ-始めよう" tabindex="-1">さあ！始めよう！ <a class="header-anchor" href="#さあ-始めよう" aria-label="Permalink to &quot;さあ！始めよう！&quot;">​</a></h1><p>ようこそ！ このページでは、約 15〜20 分で <strong>EcoCONNECTを使ってセンサーデータを読み取る</strong> まで進めます。</p><h2 id="用意するもの" tabindex="-1">用意するもの <a class="header-anchor" href="#用意するもの" aria-label="Permalink to &quot;用意するもの&quot;">​</a></h2><ul><li>EcoCONNECT メインボード（完成品）</li><li>Micro-USB ケーブル</li><li>パソコン（Windows / macOS / Linux）</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-ecoconnectメインボードをpcに接続する" tabindex="-1">1. EcoCONNECTメインボードをPCに接続する <a class="header-anchor" href="#_1-ecoconnectメインボードをpcに接続する" aria-label="Permalink to &quot;1. EcoCONNECTメインボードをPCに接続する&quot;">​</a></h3><p>Micro USBケーブルでEcoCONNECTメインボードとPCを接続します。接続すると電源LEDが一瞬点滅します。 <a href="#">EcoCONNECTのコネクターの位置</a></p><h3 id="_2-用意済みファームウェアを書き込む" tabindex="-1">2. 用意済みファームウェアを書き込む <a class="header-anchor" href="#_2-用意済みファームウェアを書き込む" aria-label="Permalink to &quot;2. 用意済みファームウェアを書き込む&quot;">​</a></h3><p>EcoCONNECT には、コードを書かなくても使える <strong>書き込み用イメージ</strong> があります。</p><ol><li>リポジトリの <code>firmware/pico2/release/</code> を開く</li><li><code>firmware/pico2/</code> の README に従い、<code>.uf2</code> を Raspberry Pi Pico にコピーする</li><li>ボードが再起動したら、最初の計測の準備完了です</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>書き込み時にはUSBケーブルを抜いたりしないでください。</p></div><h3 id="_3-センサーの値を読み取る" tabindex="-1">3. センサーの値を読み取る <a class="header-anchor" href="#_3-センサーの値を読み取る" aria-label="Permalink to &quot;3. センサーの値を読み取る&quot;">​</a></h3><p>ターミナルを開いて、センサー読み取りプログラムを実行します。</p><h3 id="_4-高度な使い方" tabindex="-1">4. 高度な使い方 <a class="header-anchor" href="#_4-高度な使い方" aria-label="Permalink to &quot;4. 高度な使い方&quot;">​</a></h3><p>ここまででセンサーの値をPCで利用することができました！ 次のステップ<a href="/AuraLinc-Community/docs/hack/remote">データを無線で送信する</a>に進みましょう。</p><h2 id="他のリソース" tabindex="-1">他のリソース <a class="header-anchor" href="#他のリソース" aria-label="Permalink to &quot;他のリソース&quot;">​</a></h2><ul><li>10 分で終わる <a href="/AuraLinc-Community/steam/recipes">レシピ</a></li><li>アイデア探しは <a href="/AuraLinc-Community/steam/examples">事例</a></li><li>先生向け：<a href="/AuraLinc-Community/steam/">ワークショップ資料</a></li></ul>',17)])])}const p=e(r,[["render",c]]);export{m as __pageData,p as default};
